create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text,role text default 'viewer',status text default 'active',linked_admission_no text,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$declare n int;begin select count(*) into n from profiles;insert into profiles(id,email,full_name,role) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',new.email),case when n=0 then 'super_admin' else 'viewer' end);return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid() and status='active'$$;
create or replace function public.role_in(r text[]) returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.my_role()=any(r),false)$$;
create table if not exists school_settings(id int primary key default 1,school_name text,tagline text,logo_url text,hero_image_url text,hero_title text,hero_text text,about_text text,principal_message text,phone text,address text);
insert into school_settings(id,school_name) values(1,'L D MODERN EDUCATION ACADEMY') on conflict(id) do nothing;
create table if not exists admissions(id uuid primary key default gen_random_uuid(),admission_no text,admission_date date,academic_session text,student_name text,class_name text,section text,roll_no text,dob date,gender text,pen_no text,apaar_id text,udise_student_id text,father_name text,mother_name text,guardian_name text,primary_phone text,email text,parent_email text,address text,district text,state text,pincode text,document_status text,tc_no text,admission_status text,created_at timestamptz default now());
create table if not exists students(id uuid primary key default gen_random_uuid(),student_name text,admission_no text,student_id text,roll_no text,class_name text,section text,father_name text,mother_name text,phone text,student_email text,parent_email text,address text,status text default 'Active',created_at timestamptz default now());
create table if not exists academics(id uuid primary key default gen_random_uuid(),academic_session text,class_name text,section text,subject text,teacher_name text,assignment_note text,created_at timestamptz default now());
create table if not exists attendance(id uuid primary key default gen_random_uuid(),date date,student_name text,admission_no text,class_name text,section text,status text,remark text,created_at timestamptz default now(),unique(date,admission_no));
create table if not exists staff_attendance(id uuid primary key default gen_random_uuid(),date date,staff_name text,employee_id text,status text,remark text,created_at timestamptz default now());
create table if not exists fees(id uuid primary key default gen_random_uuid(),date date,receipt_no text,student_name text,admission_no text,class_name text,phone text,fee_type text,installment text,total_fee numeric default 0,discount numeric default 0,paid_amount numeric default 0,due_amount numeric default 0,payment_mode text,due_date date,note text,created_at timestamptz default now());
create table if not exists exams(id uuid primary key default gen_random_uuid(),exam_name text,exam_date date,student_name text,admission_no text,class_name text,subject text,internal_marks numeric default 0,external_marks numeric default 0,max_marks numeric default 0,total_marks numeric default 0,percentage numeric default 0,grade text,result_status text,created_at timestamptz default now());
create table if not exists staff(id uuid primary key default gen_random_uuid(),employee_id text,staff_name text,staff_type text,designation text,subject text,phone text,email text,joining_date date,salary numeric default 0,status text default 'Active',created_at timestamptz default now());
create table if not exists leave(id uuid primary key default gen_random_uuid(),staff_name text,employee_id text,from_date date,to_date date,leave_type text,reason text,status text,created_at timestamptz default now());
create table if not exists payroll(id uuid primary key default gen_random_uuid(),month text,employee_id text,staff_name text,basic_salary numeric default 0,allowance numeric default 0,deduction numeric default 0,net_salary numeric default 0,payment_date date,payment_mode text,status text,created_at timestamptz default now());
create table if not exists timetable(id uuid primary key default gen_random_uuid(),class_name text,section text,day_name text,period_no int,start_time time,end_time time,subject text,teacher_name text,created_at timestamptz default now());
create table if not exists homework(id uuid primary key default gen_random_uuid(),date date,class_name text,section text,subject text,title text,description text,due_date date,teacher_name text,created_at timestamptz default now());
create table if not exists events(id uuid primary key default gen_random_uuid(),event_date date,title text,event_type text,description text,audience text,reminder text,created_at timestamptz default now());
create table if not exists notices(id uuid primary key default gen_random_uuid(),date date,title text,audience text,message text,download_url text,created_at timestamptz default now());
create table if not exists gallery(id uuid primary key default gen_random_uuid(),title text,media_type text,media_url text,event_date date,created_at timestamptz default now());
create table if not exists enquiries(id uuid primary key default gen_random_uuid(),name text,phone text,email text,message text,status text default 'New',created_at timestamptz default now());
create table if not exists transport(id uuid primary key default gen_random_uuid(),route_name text,vehicle_no text,driver_name text,driver_phone text,student_name text,pickup_point text,monthly_fee numeric default 0,created_at timestamptz default now());
create table if not exists library(id uuid primary key default gen_random_uuid(),book_code text,book_title text,author text,student_name text,issue_date date,due_date date,status text,created_at timestamptz default now());
create table if not exists income(id uuid primary key default gen_random_uuid(),date date,source text,amount numeric default 0,payment_mode text,note text,created_at timestamptz default now());
create table if not exists expenses(id uuid primary key default gen_random_uuid(),date date,category text,vendor text,amount numeric default 0,payment_mode text,note text,created_at timestamptz default now());
alter table profiles enable row level security;alter table school_settings enable row level security;
do $$declare t text;begin foreach t in array array['admissions','students','academics','attendance','staff_attendance','fees','exams','staff','leave','payroll','timetable','homework','events','notices','gallery','enquiries','transport','library','income','expenses'] loop execute format('alter table %I enable row level security',t);end loop;end$$;
drop policy if exists profiles_read on profiles;create policy profiles_read on profiles for select to authenticated using(id=auth.uid() or public.role_in(array['super_admin','admin','principal']));
drop policy if exists profiles_update on profiles;create policy profiles_update on profiles for update to authenticated using(public.role_in(array['super_admin','admin'])) with check(public.role_in(array['super_admin','admin']));
drop policy if exists school_public on school_settings;create policy school_public on school_settings for select to anon,authenticated using(true);
drop policy if exists school_write on school_settings;create policy school_write on school_settings for all to authenticated using(public.role_in(array['super_admin','admin','principal'])) with check(public.role_in(array['super_admin','admin','principal']));
do $$declare t text;begin foreach t in array array['staff','events','notices','gallery'] loop execute format('drop policy if exists public_read on %I',t);execute format('create policy public_read on %I for select to anon,authenticated using(true)',t);end loop;end$$;
drop policy if exists public_admission on admissions;create policy public_admission on admissions for insert to anon with check(admission_status='Applied');
drop policy if exists public_enquiry on enquiries;create policy public_enquiry on enquiries for insert to anon with check(true);
drop policy if exists public_result on exams;create policy public_result on exams for select to anon using(result_status='Published');
do $$declare t text;begin foreach t in array array['admissions','students','academics','attendance','staff_attendance','fees','exams','staff','leave','payroll','timetable','homework','events','notices','gallery','enquiries','transport','library','income','expenses'] loop execute format('drop policy if exists auth_read on %I',t);execute format('create policy auth_read on %I for select to authenticated using(public.my_role() is not null)',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['admissions','students','enquiries'] loop execute format('drop policy if exists admission_write on %I',t);execute format('create policy admission_write on %I for all to authenticated using(public.role_in(array[''super_admin'',''admin'',''principal'',''admission''])) with check(public.role_in(array[''super_admin'',''admin'',''principal'',''admission'']))',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['academics','staff_attendance','staff','leave','gallery'] loop execute format('drop policy if exists principal_write on %I',t);execute format('create policy principal_write on %I for all to authenticated using(public.role_in(array[''super_admin'',''admin'',''principal''])) with check(public.role_in(array[''super_admin'',''admin'',''principal'']))',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['attendance','exams','timetable','homework','events','notices'] loop execute format('drop policy if exists teacher_write on %I',t);execute format('create policy teacher_write on %I for all to authenticated using(public.role_in(array[''super_admin'',''admin'',''principal'',''teacher''])) with check(public.role_in(array[''super_admin'',''admin'',''principal'',''teacher'']))',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['fees','payroll','income','expenses'] loop execute format('drop policy if exists account_write on %I',t);execute format('create policy account_write on %I for all to authenticated using(public.role_in(array[''super_admin'',''admin'',''principal'',''accountant''])) with check(public.role_in(array[''super_admin'',''admin'',''principal'',''accountant'']))',t);end loop;end$$;
drop policy if exists transport_write on transport;create policy transport_write on transport for all to authenticated using(public.role_in(array['super_admin','admin','principal','transport'])) with check(public.role_in(array['super_admin','admin','principal','transport']));
drop policy if exists library_write on library;create policy library_write on library for all to authenticated using(public.role_in(array['super_admin','admin','principal','librarian'])) with check(public.role_in(array['super_admin','admin','principal','librarian']));